node -e "
const sqlite3 = require('better-sqlite3');
const db = new sqlite3('/workspace/world.db');
const users = db.prepare(\"SELECT * FROM users WHERE name = 'Lena Brooks'\").all();
console.log('Found', users.length, 'accounts');
users.forEach(u => {
  const parsed = {...u};
  // Parse JSON fields for display
  ['preferences_json','purchase_history_json','payment_methods_json','saved_passengers_json','address_json','skill_ids_json'].forEach(f => {
    if (parsed[f]) { try { parsed[f] = JSON.parse(parsed[f]); } catch(e) {} }
  });
  console.log(JSON.stringify(parsed, null, 2));
  console.log('---');
});
"

