  UPDATE carts 
  SET discount_amount = ?, 
      total = ?, 
      applied_promo_codes_json = ?
  WHERE cart_id = 'CART-user_03dd1ad7'
\`).run(newDiscountAmount, newTotal, JSON.stringify(appliedPromos));

